const pForms = w => {
  const o = [];
  if (w.length > 3) {
    if (w.endsWith('oes') || w.endsWith('aes')) o.push(w.slice(0, -3) + 'ao');
    if (w.endsWith('ais')) o.push(w.slice(0, -3) + 'al');
    if (w.endsWith('eis')) o.push(w.slice(0, -3) + 'el');
    if (w.endsWith('ois')) o.push(w.slice(0, -3) + 'ol');
    if (w.endsWith('ns')) o.push(w.slice(0, -2) + 'm');
    if (w.endsWith('is') && w.length > 4) o.push(w.slice(0, -2) + 'il');
    if (w.endsWith('res') || w.endsWith('zes') || w.endsWith('ses')) o.push(w.slice(0, -2));
    if (w.endsWith('s')) o.push(w.slice(0, -1));
    if (w.endsWith('a') || w.endsWith('o')) o.push(w.slice(0, -1));
  }
  return o;
};

